from math import isqrt
DIG='0123456789ABCDEFG'
def is_sq(v):
    r=isqrt(v); return r*r==v

def enum(n, require_all_bases=False):
    found=[]
    total=0
    # recursive enumerate digits, prune using base checks as soon as possible
    ds=[0]*n
    def rec(pos, md):
        nonlocal total
        if pos==n:
            total+=1
            # check all bases
            vals=[]
            for b in range(max(2,md+1),18):
                v=0
                for d in ds: v=v*b+d
                if v<4: continue
                if v<=676 or require_all_bases:
                    if not is_sq(v): return
                    if v<=676: vals.append((b,v))
            if vals:
                found.append((''.join(DIG[d] for d in ds),vals))
            return
        start=1 if pos==0 else 0
        for d in range(start,17):
            ds[pos]=d
            # quick prune: if current prefix in base md+1..17 with value <=676 must be square? can't easily prune prefix
            rec(pos+1, max(md,d))
    rec(0,0)
