    if not propagate(dom,assigned,cell_digit,value_count,base_count,digit_present,used_strings): return
    best=-1; bestcnt=10**9; bestdeg=-1
    for i,e in enumerate(E):
        if assigned[i] is not None: continue
        c=dom[i].bit_count()
        if c==0: return
        deg=len(pairs[i])
        if c<bestcnt or (c==bestcnt and deg>bestdeg): bestcnt=c; best=i; bestdeg=deg
    if best==-1:
        if sum(1 for cell in all_cells if cell_digit[cell]==0)!=16: return
        if any(base_count[b]!=3 for b in range(2,9)): return
        if any(base_count[b]<1 or base_count[b]>3 for b in range(9,18)): return
        if any(value_count[v]<1 or value_count[v]>2 for v in SQUARES): return
        if any(digit_present[d]==0 for d in range(1,17)): return
        SOLS.append((assigned.copy(),cell_digit.copy()))
        return
    e=E[best]; m=dom[best]
    while m and len(SOLS)<LIMIT:
        lsb=m&-m; oi=lsb.bit_length()-1; m-=lsb
        b,v,ds=e['domain'][oi]; s=''.join(DIGITS[d] for d in ds)
        if s in used_strings or value_count[v]>=2 or base_count[b]>=3: continue
        newdom=dom.copy(); newdom[best]=lsb
        new_cell=cell_digit.copy(); ok=True; new_cells=[]
        for pos,cell in enumerate(e['cells']):
            d=ds[pos]
            if new_cell[cell] is not None:
                if new_cell[cell]!=d: ok=False;break
            else:
                new_cell[cell]=d; new_cells.append((cell,d))
        if not ok: continue
        for j,shares in pairs[best].items():
            if assigned[j] is not None: continue
            mask=newdom[j]
            for pos,posj,cell in shares:
                mask &= masks[j][posj][ds[pos]]
                if mask==0: break
            if mask==0: ok=False;break
            newdom[j]=mask
        if not ok: continue
        assigned[best]=oi
        nv=value_count.copy(); nv[v]+=1
        nb=base_count.copy(); nb[b]+=1
        ndp=digit_present.copy()
        for cell,d in new_cells: ndp[d]+=1
        nus=used_strings.copy(); nus[s]=nus.get(s,0)+1
        search(newdom,assigned,new_cell,nv,nb,ndp,nus)
        assigned[best]=None

search(dom0,assigned,{cell:None for cell in all_cells},value_count,base_count,digit_present,used_strings)
print('solutions',len(SOLS),'nodes',NODE[0],'time',time.time()-start)
# analyze variance
